const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value)||0);
const dateBR=date=>date?new Intl.DateTimeFormat('pt-BR').format(parseDate(date)):'—';
const today=()=>{const d=new Date();d.setHours(0,0,0,0);return d};
const isoToday=()=>formatISO(today());
function parseDate(value){const [y,m,d]=value.split('-').map(Number);return new Date(y,m-1,d)}
function formatISO(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function shiftDays(date,days){const d=new Date(date);d.setDate(d.getDate()+days);return d}
function periodBounds(type=dashboardPeriod){const now=today();let start,end=new Date(now);if(type==='lastMonth'){start=new Date(now.getFullYear(),now.getMonth()-1,1);end=new Date(now.getFullYear(),now.getMonth(),0)}else if(type==='month'){start=new Date(now.getFullYear(),now.getMonth(),1)}else if(type==='all'){start=new Date(2000,0,1)}else if(type==='custom'){start=$('periodStart').value?parseDate($('periodStart').value):new Date(now.getFullYear(),now.getMonth(),1);end=$('periodEnd').value?parseDate($('periodEnd').value):now}else{start=shiftDays(now,-29)}return{start,end}}
function inRange(value,range){if(!value)return false;const d=parseDate(String(value).slice(0,10));return d>=range.start&&d<=range.end}
function previousBounds(range){const days=Math.round((range.end-range.start)/86400000)+1;return{start:shiftDays(range.start,-days),end:shiftDays(range.start,-1)}}
function planMonths(plan){return({'30d':1,'3m':3,'6m':6,'1y':12})[plan]||1}
function trendText(current,previous){if(!previous)return current?'Primeiro resultado neste comparativo':'Sem movimentação anterior';const pct=Math.round(((current-previous)/previous)*100);return `${pct>=0?'+':''}${pct}% vs. período anterior`}
function diffDays(date){return Math.round((parseDate(date)-today())/86400000)}
function planLabel(plan){return ({'30d':'30 dias','3m':'3 meses','6m':'6 meses','1y':'1 ano'})[plan]||plan}
function addMonths(date,months){const day=date.getDate();date.setDate(1);date.setMonth(date.getMonth()+months);const last=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();date.setDate(Math.min(day,last))}
function calculateDue(start,plan){const d=parseDate(start);if(plan==='30d')d.setDate(d.getDate()+30);if(plan==='3m')addMonths(d,3);if(plan==='6m')addMonths(d,6);if(plan==='1y')addMonths(d,12);return formatISO(d)}
function statusOf(c){if(c.cancelled)return{key:'cancelados',label:'Cancelado',color:'gray'};if(c.lifetime)return{key:'ativos',label:'Vitalício',color:'green'};const days=diffDays(c.dueDate);if(days<0)return{key:'vencidos',label:'Vencido',color:'red'};if(days===0)return{key:'hoje',label:'Vence hoje',color:'amber'};if(days<=5)return{key:'proximos',label:`Vence em ${days} dia${days>1?'s':''}`,color:'amber'};return{key:'ativos',label:'Ativo',color:'green'}}
function escapeHTML(text=''){return String(text).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]))}
function parseStoredNotes(value,row){try{if(typeof value==='string'&&value.startsWith(DEVICE_MARKER)){const p=JSON.parse(value.slice(DEVICE_MARKER.length));return{notes:p.notes||'',devices:p.devices||[],resellerName:p.resellerName||'',resellerPhone:p.resellerPhone||'',cost:Number(p.cost)||0}}}catch{}return{notes:value||'',devices:[],resellerName:'',resellerPhone:'',cost:0}}
function toClient(row){const p=parseStoredNotes(row.notes,row);return{id:row.id,name:row.name,phone:row.phone,appName:row.app_name,startDate:row.start_date,plan:row.plan,value:Number(row.amount),cost:Number(row.cost??p.cost)||0,resellerId:row.reseller_id||null,resellerName:p.resellerName,resellerPhone:p.resellerPhone,payment:row.payment_method,notes:p.notes,devices:p.devices.length?p.devices:[{device:'TV 1',appName:row.app_name||'',mac:'',key:'',screens:Number(row.screens)||1}],dueDate:row.due_date,cancelled:row.cancelled,lifetime:!!row.lifetime,screens:Number(row.screens)||1,createdAt:row.created_at}}
function fromClient(d){return{name:d.name,phone:d.phone,app_name:d.devices[0]?.appName||'',start_date:d.startDate,plan:d.plan,amount:d.value,cost:Number(d.cost)||0,reseller_id:d.resellerId||null,payment_method:d.payment,notes:DEVICE_MARKER+JSON.stringify({notes:d.notes||'',devices:d.devices||[],resellerName:d.resellerName||'',resellerPhone:d.resellerPhone||'',cost:Number(d.cost)||0}),due_date:d.dueDate,cancelled:!!d.cancelled,lifetime:!!d.lifetime,screens:Number(d.screens)||1}}
function authHeaders(extra={}){return{'apikey':SUPABASE_KEY,'Authorization':`Bearer ${session?.access_token||SUPABASE_KEY}`,'Content-Type':'application/json',...extra}}
async function api(path,options={}){const res=await fetch(`${SUPABASE_URL}${path}`,{...options,headers:authHeaders(options.headers||{})});const text=await res.text();let data={};try{data=text?JSON.parse(text):{}}catch{data={message:text}}if(!res.ok)throw new Error(data.error||data.msg||data.message||data.error_description||'Não foi possível concluir.');return data}
function storeSession(data){session=data;localStorage.setItem(SESSION_KEY,JSON.stringify(data))}
function clearSession(){session=null;localStorage.removeItem(SESSION_KEY)}
async function restoreSession(){try{const saved=JSON.parse(localStorage.getItem(SESSION_KEY));if(!saved?.refresh_token)return false;if(saved.expires_at&&saved.expires_at*1000>Date.now()+60000){session=saved;return true}const fresh=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:saved.refresh_token})});fresh.expires_at=Math.floor(Date.now()/1000)+fresh.expires_in;storeSession(fresh);return true}catch{clearSession();return false}}
async function loadData(){const [clientRows,renewalRows,resellerRows,apps]=await Promise.all([api('/rest/v1/clients?select=*&order=due_date.asc'),api('/rest/v1/renewals?select=*&order=created_at.desc'),api('/rest/v1/resellers?select=id,name,phone,notes&active=eq.true&order=name.asc'),api('/rest/v1/client_apps?select=*&active=eq.true&order=created_at.asc')]);resellers=resellerRows;const rm=new Map(resellers.map(r=>[r.id,r])),am=new Map();apps.forEach(a=>{const l=am.get(a.client_id)||[];l.push({device:a.device_name,appName:a.app_name,email:a.login_email||'',username:a.login_username||'',password:a.login_password||'',mac:a.mac||'',key:a.app_key||'',screens:Number(a.screens)||1,appPrice:a.app_price==null?'':Number(a.app_price)});am.set(a.client_id,l)});clients=clientRows.map(row=>{const c=toClient(row),r=rm.get(row.reseller_id);if(r){c.resellerId=r.id;c.resellerName=r.name;c.resellerPhone=r.phone||''}if(am.has(row.id))c.devices=am.get(row.id);return c});renewals=renewalRows;render()}
