async function saveAndroidApp(){const name=$('newAndroidAppName').value.trim(),price=$('newAndroidAppPrice').value===''?null:Number($('newAndroidAppPrice').value);if(!name){alert('Digite o nome do aplicativo.');return}try{await api('/rest/v1/android_apps?on_conflict=owner_id,name',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({name,price,active:true})});$('newAndroidAppName').value='';$('newAndroidAppPrice').value='';await loadAndroidApps();showToast('Aplicativo cadastrado.')}catch(e){alert(e.message)}}
function setPanelView(view){const apps=view==='apps',resellers=view==='resellers',finance=view==='finance',special=apps||resellers||finance;document.querySelector('.topbar').hidden=special;document.querySelector('.analytics').hidden=!finance;document.querySelector('.monthly-report').hidden=!finance;document.querySelector('.summary-grid').hidden=special;document.querySelector('.panel:not(#resellersSection):not(#androidAppsSection):not(.monthly-report)').hidden=special;$('resellersSection').hidden=!resellers;$('androidAppsSection').hidden=!apps;if(resellers)renderResellers();if(apps)loadAndroidApps();if(finance){renderAnalytics();renderMonthlyReport()}}
function clientRow(c){const s=statusOf(c),days=c.lifetime?999:diffDays(c.dueDate),hint=c.lifetime?'Sem vencimento':days<0?`${Math.abs(days)} dia${Math.abs(days)>1?'s':''} atrasado`:days===0?'É hoje':days===1?'Amanhã':`Faltam ${days} dias`;return `<tr><td class="client-name"><strong>${escapeHTML(c.name)}</strong><span>${escapeHTML(c.phone)}</span></td><td>${escapeHTML((c.devices||[]).map(d=>d.appName).join(', '))}</td><td>${c.lifetime?'Vitalício':planLabel(c.plan)} · ${c.screens} tela(s)</td><td class="date-cell"><strong>${c.lifetime?'Vitalício':dateBR(c.dueDate)}</strong><span>${c.cancelled?'Sem renovação':hint}</span></td><td><strong>${money(c.value)}</strong></td><td><span class="badge ${s.color}">${s.label}</span></td><td><div class="actions">${c.lifetime?'':`<button class="action-btn renew" onclick="renewClient('${c.id}')">Renovar</button>`}<button class="action-btn" onclick="sendCharge('${c.id}')">WhatsApp</button><button class="action-btn" onclick="showClientData('${c.id}')">Ver dados</button><details class="more"><summary class="action-btn">•••</summary><div class="more-menu"><button onclick="editClient('${c.id}')">Editar</button><button onclick="showHistory('${c.id}')">Histórico</button><button onclick="toggleCancel('${c.id}')">${c.cancelled?'Reativar':'Cancelar'}</button><button class="danger" onclick="deleteClient('${c.id}')">Excluir</button></div></details></div></td></tr>`}
function configureClientPhoneRequirement(isResellerClient){const phone=$('phone'),hint=$('clientPhoneHint');phone.required=!isResellerClient;phone.placeholder=isResellerClient?'Opcional — a cobrança vai para o revendedor':'(27) 99999-9999';hint.textContent=isResellerClient?'Opcional: será usado o WhatsApp do revendedor.':''}
function openForm(c=null){$('clientForm').reset();delete $('clientForm').dataset.detectedDue;$('clientId').value=c?.id||'';$('formTitle').textContent=c?'Editar cliente':'Novo cliente';$('startDate').value=c?.startDate||isoToday();$('plan').value=c?.plan||'30d';$('screens').value=String(c?.screens||1);$('lifetime').checked=!!c?.lifetime;renderDevices(c?.devices||[newDevice()]);if(c){$('name').value=c.name;$('phone').value=c.phone||'';$('value').value=c.value;$('resellerName').value=c.resellerName||'';$('resellerPhone').value=c.resellerPhone||'';$('payment').value=c.payment;$('notes').value=c.notes||''}configureClientPhoneRequirement(!!c?.resellerId||!!c?.resellerName);updatePreview();$('clientDialog').showModal()}
function openClientForReseller(id){const r=resellers.find(x=>x.id===id);openForm();if(r){$('resellerName').value=r.name;$('resellerPhone').value=r.phone||'';configureClientPhoneRequirement(true)}}
function updatePreview(){const lifetime=$('lifetime').checked;$('plan').disabled=lifetime;$('datePreview').textContent=lifetime?'Vitalício — sem vencimento':$('startDate').value?dateBR(calculateDue($('startDate').value,$('plan').value)):'—'}
function deviceDataText(d,i){const access=appUsesMac(d.appName)?`\nMAC: ${d.mac||'—'}\nKey: ${d.key||'—'}`:'',email=appCode(d.appName)==='clouddy'?`\nE-mail: ${d.email||'—'}`:'';return `${d.device||`Aparelho ${i+1}`}\nAplicativo Android: ${d.appName||'—'}${email}\nUsuário: ${d.username||'—'}\nSenha: ${d.password||'—'}${access}\nTelas: ${d.screens||1}\nValor do aplicativo: ${d.appPrice!==''&&d.appPrice!=null?money(d.appPrice):'Grátis / não informado'}`}
function showClientData(id){const c=clients.find(x=>x.id===id);if(!c)return;clientDataId=id;const devices=c.devices||[];clientDataText=`Cliente: ${c.name}\nWhatsApp: ${c.phone}\nPlano: ${c.lifetime?'Vitalício':planLabel(c.plan)}\nCadastro: ${dateBR(c.startDate)}\nVencimento: ${c.lifetime?'Sem vencimento':dateBR(c.dueDate)}\nValor: ${money(c.value)}\nRevendedor: ${c.resellerName||'Cliente direto'}\n\n`+devices.map(deviceDataText).join('\n\n');$('clientDataTitle').textContent=c.name;$('clientDataContent').innerHTML=`<div class="data-summary"><div><span>WhatsApp</span><strong>${escapeHTML(c.phone)}</strong></div><div><span>Plano</span><strong>${c.lifetime?'Vitalício':escapeHTML(planLabel(c.plan))}</strong></div><div><span>Vencimento</span><strong>${c.lifetime?'Sem vencimento':dateBR(c.dueDate)}</strong></div><div><span>Responsável</span><strong>${escapeHTML(c.resellerName||'Cliente direto')}</strong></div></div>`+devices.map((d,i)=>{const macKey=appUsesMac(d.appName)?`<div><span>MAC</span><strong>${escapeHTML(d.mac||'—')}</strong></div><div><span>Key</span><strong>${escapeHTML(d.key||'—')}</strong></div>`:'';return `<section class="data-device"><div class="data-device-head"><div><span>${escapeHTML(d.device||`Aparelho ${i+1}`)}</span><h3>${escapeHTML(d.appName||'Aplicativo não informado')}</h3></div><b>Aplicativo Android</b></div><div class="data-fields"><div><span>Usuário</span><strong>${escapeHTML(d.username||'—')}</strong></div><div><span>Senha</span><strong>${escapeHTML(d.password||'—')}</strong></div>${macKey}<div><span>Telas</span><strong>${d.screens||1}</strong></div><div><span>Valor do aplicativo</span><strong>${d.appPrice!==''&&d.appPrice!=null?money(d.appPrice):'Grátis / não informado'}</strong></div></div></section>`}).join('');$('moveClientReseller').innerHTML=`<option value="">Cliente direto</option>`+resellers.map(r=>`<option value="${r.id}" ${c.resellerId===r.id?'selected':''}>${escapeHTML(r.name)}</option>`).join('');$('clientDataDialog').showModal()}
async function moveClientToReseller(){const c=clients.find(x=>x.id===clientDataId);if(!c)return;const id=$('moveClientReseller').value,r=resellers.find(x=>x.id===id);try{setBusy(true);c.resellerId=id||null;c.resellerName=r?.name||'';c.resellerPhone=r?.phone||'';await api(`/rest/v1/clients?id=eq.${c.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({reseller_id:c.resellerId,notes:fromClient(c).notes})});await addHistory(c,'update',c.dueDate,c.dueDate,`Cliente movido para ${c.resellerName||'Cliente direto'}`);$('clientDataDialog').close();render();showToast(`Cliente movido para ${c.resellerName||'Cliente direto'}.`)}catch(e){alert(e.message)}finally{setBusy(false)}}
function editClient(id){openForm(clients.find(c=>c.id===id))}
async function addHistory(c,type,oldDue,newDue,description,amount=0){const rows=await api('/rest/v1/renewals',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({client_id:c.id,event_type:type,plan:c.plan,amount,previous_due_date:oldDue,new_due_date:newDue,description})});if(rows[0])renewals.unshift(rows[0]);return rows[0]}
async function renewClient(id){const c=clients.find(c=>c.id===id);if(!c)return;const base=diffDays(c.dueDate)>=0?c.dueDate:isoToday(),oldDue=c.dueDate,newDue=calculateDue(base,c.plan);try{setBusy(true);await api(`/rest/v1/clients?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({due_date:newDue,cancelled:false})});await addHistory(c,'renewal',oldDue,newDue,`Renovado por ${planLabel(c.plan)}`,c.value);c.dueDate=newDue;c.cancelled=false;c.lastRenewedAt=isoToday();render();showToast(`Renovação de ${c.name} registrada.`);showMessage(c,'renewal')}catch(e){alert(e.message)}finally{setBusy(false)}}
async function toggleCancel(id){const c=clients.find(c=>c.id===id);if(!c)return;try{setBusy(true);const cancelled=!c.cancelled;await api(`/rest/v1/clients?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cancelled})});await addHistory(c,cancelled?'cancel':'reactivate',c.dueDate,c.dueDate,cancelled?'Cliente cancelado':'Cliente reativado');c.cancelled=cancelled;render()}catch(e){alert(e.message)}finally{setBusy(false)}}
async function deleteClient(id){const c=clients.find(c=>c.id===id);if(!c||!confirm(`Excluir definitivamente o cadastro de ${c.name}?`))return;try{setBusy(true);await api(`/rest/v1/clients?id=eq.${id}`,{method:'DELETE'});clients=clients.filter(x=>x.id!==id);renewals=renewals.filter(x=>x.client_id!==id);render();showToast('Cliente excluído.')}catch(e){alert(e.message)}finally{setBusy(false)}}
async function showHistory(id){const c=clients.find(c=>c.id===id);if(!c)return;try{const rows=await api(`/rest/v1/renewals?client_id=eq.${id}&select=*&order=created_at.desc`);$('historyTitle').textContent=c.name;$('historyContent').innerHTML=rows.map(h=>`<div class="history-item"><strong>${escapeHTML(h.description)}</strong><span>${dateBR(h.created_at.slice(0,10))}${Number(h.amount)?` · ${money(h.amount)}`:''}</span></div>`).join('')||'<p>Nenhum registro encontrado.</p>';$('historyDialog').showModal()}catch(e){alert(e.message)}}
function activationMessage(c,renewal=false){const access=(c.devices||[]).map((d,i)=>{const email=appCode(d.appName)==='clouddy'?`\nE-mail: ${d.email||'—'}`:'',macKey=appUsesMac(d.appName)?`\nMAC: ${d.mac||'—'}\nKey: ${d.key||'—'}`:'';return `\n${d.device||`Aparelho ${i+1}`}\nAplicativo: ${d.appName||'—'}${email}\nUsuário: ${d.username||'—'}\nSenha: ${d.password||'—'}${macKey}`}).join('\n');return `Olá, ${c.name}! Seu pacote de ${c.lifetime?'Vitalício':planLabel(c.plan)} foi ${renewal?'renovado':'ativado'} com sucesso.\n${access}\n\nData da ${renewal?'renovação':'contratação'}: ${dateBR(renewal?(c.lastRenewedAt||isoToday()):c.startDate)}\nVencimento: ${c.lifetime?'Sem vencimento':dateBR(c.dueDate)}\n\nAgradecemos pela preferência!\nJS Tech — conectado com você.`}
const PIX_KEY='f721b8e2-1ad2-469c-b45d-653e58880ba2';
function chargeMessage(c){const reseller=c.resellerName?`Olá, ${c.resellerName}! Tudo bem?\n\nO cliente ${c.name}, da sua revenda,`:`Olá, ${c.name}! Tudo bem?\n\nSeu plano`;return `${reseller} de ${c.lifetime?'Vitalício':planLabel(c.plan)} ${!c.lifetime?(diffDays(c.dueDate)<0?`venceu em ${dateBR(c.dueDate)}`:`vence em ${dateBR(c.dueDate)}`):'está ativo'}. O valor para renovação é ${money(c.value)}.\n\nPagamento via Pix\nChave Pix: ${PIX_KEY}\nTitular: Julio Viana de Oliveira\n\nApós o pagamento, envie o comprovante para confirmar a renovação.\nJS Tech — conectado com você.`}
function showMessage(c,type){messageClientId=c.id;$('messageTitle').textContent=type==='charge'?'Aviso de vencimento':type==='renewal'?'Renovação realizada':'Ativação realizada';$('messageText').value=type==='charge'?chargeMessage(c):activationMessage(c,type==='renewal');$('messageDialog').showModal()}
function sendCharge(id){const c=clients.find(c=>c.id===id);if(c)showMessage(c,'charge')}
function whatsappNumber(phone){let n=phone.replace(/\D/g,'');if(n.length===10||n.length===11)n='55'+n;return n}

$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginError').style.color='';$('loginError').textContent='';const username=$('loginUser').value.trim().toLowerCase(),password=$('loginPassword').value;if(username!==ADMIN_USER){$('loginError').textContent='Usuário ou senha incorretos.';return}try{setBusy(true);let data;try{data=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:ADMIN_EMAIL,password})})}catch{const redirect=encodeURIComponent(location.origin);data=await api(`/auth/v1/signup?redirect_to=${redirect}`,{method:'POST',body:JSON.stringify({email:ADMIN_EMAIL,password})});if(!data.access_token){$('loginError').style.color='#43d99c';$('loginError').textContent='Primeiro acesso criado. Confirme o e-mail enviado para juliosirlene43@gmail.com e depois clique em Entrar.';return}}data.expires_at=Math.floor(Date.now()/1000)+data.expires_in;storeSession(data);await enterApp()}catch(e){$('loginError').style.color='';$('loginError').textContent='Não foi possível entrar. Confira o usuário e a senha.'}finally{setBusy(false)}});
$('logoutBtn').addEventListener('click',async()=>{try{await api('/auth/v1/logout',{method:'POST'})}catch{}clearSession();clients=[];renewals=[];showLogin()});
$('clientForm').addEventListener('submit',async e=>{e.preventDefault();const id=$('clientId').value,existing=clients.find(c=>c.id===id),oldDue=existing?.dueDate||null,lifetime=$('lifetime').checked,devices=getDevices(),appCost=devices.reduce((total,d)=>total+(d.appPrice===''?0:Number(d.appPrice)||0),0),data={name:$('name').value.trim(),phone:$('phone').value.trim(),devices,startDate:$('startDate').value,plan:$('plan').value,value:Number($('value').value),cost:appCost,resellerName:$('resellerName').value.trim(),resellerPhone:$('resellerPhone').value.trim(),payment:$('payment').value,notes:$('notes').value.trim(),screens:Number($('screens').value)||1,lifetime,cancelled:existing?.cancelled||false};data.dueDate=lifetime?(existing?.dueDate||calculateDue(data.startDate,data.plan)):($('clientForm').dataset.detectedDue||calculateDue(data.startDate,data.plan));try{setBusy(true);data.resellerId=await ensureReseller(data.resellerName,data.resellerPhone);if(existing){await api(`/rest/v1/clients?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(fromClient(data))});await syncClientApps(id,data);Object.assign(existing,data);await addHistory(existing,'update',oldDue,data.dueDate,`Cadastro atualizado${lifetime?' · Vitalício':''}`);$('clientDialog').close();render();showToast('Cadastro atualizado.')}else{const rows=await api('/rest/v1/clients',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(fromClient(data))});const c=toClient(rows[0]);await syncClientApps(c.id,data);Object.assign(c,data);clients.push(c);await addHistory(c,'sale',null,c.dueDate,`Venda cadastrada: ${lifetime?'Vitalício':planLabel(c.plan)}`,c.value);$('clientDialog').close();render();showMessage(c,'activation')}}catch(e){alert(e.message)}finally{setBusy(false)}});
document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>$('clientDialog').close()));document.querySelectorAll('.close-message').forEach(b=>b.addEventListener('click',()=>$('messageDialog').close()));document.querySelectorAll('.close-history').forEach(b=>b.addEventListener('click',()=>$('historyDialog').close()));
