$('newResellerBtn').addEventListener('click',()=>{$('resellerForm').reset();$('resellerDialog').showModal()});
$('resellerForm').addEventListener('submit',async e=>{e.preventDefault();try{setBusy(true);await api('/rest/v1/resellers?on_conflict=owner_id,name',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({name:$('newResellerName').value.trim(),phone:$('newResellerPhone').value.trim(),notes:$('newResellerNotes').value.trim(),active:true})});$('resellerDialog').close();await loadData();setPanelView('resellers');showToast('Revendedor cadastrado. Agora adicione os clientes dele.')}catch(e){alert(e.message)}finally{setBusy(false)}});
$('newClientBtn').addEventListener('click',()=>openForm());$('addDeviceBtn').addEventListener('click',()=>{const d=getDevices();d.push(newDevice(`TV ${d.length+1}`));renderDevices(d)});$('emptyAddBtn').addEventListener('click',()=>openForm());$('startDate').addEventListener('change',updatePreview);$('plan').addEventListener('change',updatePreview);$('lifetime').addEventListener('change',updatePreview);$('searchInput').addEventListener('input',render);$('sortSelect').addEventListener('change',render);$('resellerSearch').addEventListener('input',renderResellers);$('saveAndroidAppBtn').addEventListener('click',saveAndroidApp);
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.view){setPanelView(b.dataset.view);return}setPanelView('clients');activeFilter=b.dataset.filter;render()}));
document.querySelectorAll('.period-btn').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.period-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');dashboardPeriod=b.dataset.period;$('customDates').hidden=dashboardPeriod!=='custom';renderAnalytics()}));
