$('copyMessageBtn').addEventListener('click',async()=>{await navigator.clipboard.writeText($('messageText').value);showToast('Mensagem copiada.')});$('openWhatsappBtn').addEventListener('click',()=>{const c=clients.find(c=>c.id===messageClientId);if(c){const destination=c.resellerId||c.resellerName?c.resellerPhone:c.phone;if(!destination){alert('Cadastre o WhatsApp do revendedor responsável.');return}window.open(`https://wa.me/${whatsappNumber(destination)}?text=${encodeURIComponent($('messageText').value)}`,'_blank','noopener')}});
