$('importInput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.clients))throw new Error();if(confirm(`Importar ${data.clients.length} cliente(s) para o banco?`)){setBusy(true);for(const item of data.clients){const rows=await api('/rest/v1/clients',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(fromClient(item))});if(rows[0])await addHistory(toClient(rows[0]),'sale',null,rows[0].due_date,'Venda importada',Number(rows[0].amount||0))}await loadData();showToast('Backup importado.')}}catch{alert('Este arquivo de backup não é válido ou não pôde ser importado.')}finally{setBusy(false);e.target.value=''}});
$('todayText').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date());
$('periodStart').value=formatISO(new Date(today().getFullYear(),today().getMonth(),1));$('periodEnd').value=isoToday();
function renderMonthlyReport(){const months=[];const now=today();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const sales=renewals.filter(r=>['sale','renewal'].includes(r.event_type)&&String(r.created_at||'').slice(0,7)===key),fallback=clients.filter(c=>String(c.startDate||'').slice(0,7)===key),rows=sales.length?sales:fallback.map(c=>({amount:c.value})),total=rows.reduce((sum,r)=>sum+Number(r.amount||0),0);months.push({label:new Intl.DateTimeFormat('pt-BR',{month:'short',year:'numeric'}).format(d),count:rows.length,total})}const max=Math.max(...months.map(m=>m.total),1);$('monthlyReport').innerHTML=months.map(m=>`<article class="month-card"><div><span>${m.label}</span><strong>${money(m.total)}</strong></div><small>${m.count} venda${m.count===1?'':'s'}/renovaç${m.count===1?'ão':'ões'}</small><div class="month-bar"><i style="width:${Math.round(m.total/max*100)}%"></i></div></article>`).join('')}
function parseM3UUrl(value=''){try{const u=new URL(value);const q=u.searchParams;const username=q.get('username')||q.get('user')||'';const password=q.get('password')||q.get('pass')||'';const exp=q.get('exp_date')||q.get('expires')||'';return{username,password,due:exp&&/^\d+$/.test(exp)?new Date(Number(exp)*1000):null}}catch{return{username:'',password:'',due:null}}}
function activationFromDue(dueDate,plan,reportedDate=''){if(!dueDate)return reportedDate;const d=parseDate(dueDate);if(plan==='1y')d.setFullYear(d.getFullYear()-1);else if(plan==='6m')d.setMonth(d.getMonth()-6);else if(plan==='3m')d.setMonth(d.getMonth()-3);else if(plan==='30d')d.setDate(d.getDate()-30);else return reportedDate;return formatISO(d)}
async function checkM3UDetails(value,row,status){const parsed=parseM3UUrl(value),user=row.querySelector('[data-device="username"]'),pass=row.querySelector('[data-device="password"]');if(parsed.username)user.value=parsed.username;if(parsed.password)pass.value=parsed.password;if(!parsed.username||!parsed.password){status.textContent='Cole uma URL completa com usuário e senha.';return}status.textContent='Verificando todos os dados disponíveis…';try{const info=await api('/functions/v1/check-m3u',{method:'POST',body:JSON.stringify({url:value})});if(info.username)user.value=info.username;if(info.password)pass.value=info.password;if(info.customerName&&!$('name').value.trim())$('name').value=info.customerName;if(info.customerPhone&&!$('phone').value.trim())$('phone').value=info.customerPhone;const screen=row.querySelector('[data-device="screens"]');if(screen&&info.maxConnections){screen.value=String(Math.min(10,Number(info.maxConnections)||1));const total=[...document.querySelectorAll('.device-entry [data-device="screens"]')].reduce((n,s)=>n+(Number(s.value)||1),0);$('screens').value=String(Math.min(10,total))}let detectedPlan=$('plan').value;if(info.createdDate&&info.dueDate){const days=Math.round((parseDate(info.dueDate)-parseDate(info.createdDate))/86400000);detectedPlan=days<=45?'30d':days<=120?'3m':days<=220?'6m':'1y';$('plan').value=detectedPlan}const activationDate=activationFromDue(info.dueDate,detectedPlan,info.createdDate);if(activationDate)$('startDate').value=activationDate;if(info.dueDate&&!$('lifetime').checked){$('clientForm').dataset.detectedDue=info.dueDate;$('datePreview').textContent=dateBR(info.dueDate)}updatePreview();if(info.dueDate&&!$('lifetime').checked)$('datePreview').textContent=dateBR(info.dueDate);status.textContent=`✓ ${info.customerName?'Cliente: '+info.customerName+' · ':''}${info.customerPhone?'Telefone: '+info.customerPhone+' · ':''}${activationDate?'Criado em '+dateBR(activationDate)+' · ':''}${info.dueDate?'Vence em '+dateBR(info.dueDate):'Vencimento não informado'} · ${info.maxConnections||1} tela(s)`}catch(e){status.textContent=e.message||'Não foi possível consultar esta URL.'}}
